	sections = {
		{
			title = "Обзор",
			text = [=[Ферма Гроль'дома — свиная ферма {link:orcs}орк{/link}ов на дороге между Перекрестком и {link:durotar}Дуротар{/link}ом, одна из многих, что появились с тех пор, как был основан {link:orgrimmar}Оргриммар{/link}. Это тихое место загонов и свиней. Ее хозяин, Кранал Фисс, — шаман Орды. Тех, кто хочет укротить огонь, он посылает к тайному святилищу в Дуротаре и просит принести ему факел обратно горящим.]=],
		},
	},
})

Translate("ruRU", "fray-island", {
