	sections = {
		{
			title = "Обзор",
			text = [=[Остров Битв — маленький сухой остров у восточного берега Степей. Его хозяин, Кланнок Маклауд, называет себя Островитянином и держит ристалище для воинов всех народов. Те, кто хочет у него учиться, должны сперва пройти Схватку: они выходят в середину толпы и бьются с одним противником за другим, пока к ним не выйдет сам чемпион.]=],
