Translate("ruRU", "gazlowe", {
	title = "Газлоу",
	subtitle = "Хозяин Кабестана",
	found = "Кабестан",
	hint = "Поговорите с гоблином, который управляет портом Кабестан.",
	allegiance = "Картель Хитрая Шестеренка · Кабестан",
	sections = {
		{
			title = "Обзор",
			text = [=[Газлоу — гоблин, который основал {link:ratchet}Кабестан{/link} и правит им по сей день. По ремеслу он строитель, по натуре — купец. Когда {link:orcs}орк{/link}и пришли в {link:kalimdor}Калимдор{/link}, {link:thrall}Тралл{/link} нанял его главным инженером нового государства — {link:durotar}Дуротара{/link}, и его бригады помогали возводить стены {link:orgrimmar}Оргриммара{/link}. Тралл щедро ему заплатил. На это золото Газлоу построил собственный порт в устье реки Строптивой, где торговать может всякий, пока платит.]=],
		},
		{
			title = "Значение",
			text = [=[Газлоу — старейший друг Орды среди гоблинов. Его порт — нейтральная земля, открытая и для {link:alliance}Альянса{/link}, но его расположение к {link:orcs}орк{/link}ам хорошо известно. Через {link:ratchet}Кабестан{/link} идет многое из того, что {link:horde}Орда{/link} покупает за морем.]=],
		},
