• Он основал {link:ratchet}Кабестан{/link} как порт {link:steamwheedle-cartel}Картеля Хитрая Шестеренка{/link}.
• Он послал своего человека {link:rezlak}Резлак{/link}а и дальше помогать {link:orcs}орк{/link}ам в Дуротаре.
• Он покровительствует гоблинам-гонщикам Тысячи Игл и добывает детали для их машин.
• Он построил в Кабестане обсерваторию и ждет для нее линзы.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О жизни гоблина до {link:durotar}Дуротар{/link}а здесь написано мало. Эта запись хранит лишь то, что открывают его дела и его порт.]=],
		},
	},
	chapters = {
		{
			title = "Флибустьеры",
			hint = "Прогоните пиратов с побережья к югу от Кабестана.",
			text = [=[Торговые принцы вкладывают золото в свои флоты, и все же пираты из Флибустьеров Южных морей грабят его корабли. Газлоу ворчит, что адмирал флотов делает слишком мало. Когда пираты захватили его товары, среди которых были линза для обсерватории и ящик сапог из Пиратской бухты, он нанял других, чтобы вернуть их.]=],
		},
		{
			title = "Капитан корабля «Беспечный»",
			hint = "Получите награду за голову барона пиратов.",
			text = [=[Газлоу назначил награду за барона Лонгшора, уроженца {link:gilneas}Гилнеас{/link}а, который ведет Флибустьеров, и просил доставить его останки в таком виде, чтобы их можно было узнать. Когда дело было сделано, он признался, что однажды видел, как корабль барона скользит по открытому морю, и счел это прекрасным зрелищем.]=],
		},
		{
			title = "Акула",
			hint = "Откликнитесь на призыв к рыболовам, вывешенный в Кабестане.",
			text = [=[Огромная акула стала кружить в водах у причала, нападая на матросов и малые лодки. Портовые рабочие прозвали ее Брууз, и вскоре ни одна команда не решалась войти в воду. Газлоу назначил награду за ее плавник. Когда плавник принесли, он сказал, что, пожалуй, положит его себе в суп, чтобы посмеяться последним.]=],
		},
	},
	mentions = {
		{ text = "Пропавший груз" },
		{ text = "Пропавший груз: ответ начальника причала" },
		{ text = "Гоблинское покровительство" },
		{ text = "Гоблинское покровительство: потерянный регулятор топлива" },
