Translate("ruRU", "mankrik", {
	title = "Манкрик",
	subtitle = "Скорбящий воин",
	found = "Перекресток",
	hint = [=[Поговорите с орком, который смотрит на горизонт с Перекрестка.]=],
	allegiance = "Орда",
	sections = {
		{
			title = "Обзор",
			text = [=[Манкрик — {link:orcs}орк{/link}-воин с Перекрестка. Он и его жена сражались бок о бок с {link:tauren}таурен{/link}ами в маленьком лагере, когда их смяли {link:quilboar}свинобраз{/link}ы. Она одна сдерживала троих. Он увел за собой других, а когда обернулся, увидел, как она пала. Потом свалили и его. Друид-таурен нашел его на Золотом Пути и перевязал его раны. Теперь он стоит на Перекрестке от рассвета до заката, глядя на горизонт, и с тех пор убивает каждого свинобраза, какого встретит.]=],
		},
		{
			title = "Значение",
			text = [=[Его горе известно каждому, кто проходит через {link:corin-s-crossing}Перекресток{/link}. Для многих он — свидетельство того, чего стоит война со {link:quilboar}свинобраз{/link}ами.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он поклялся отомстить {link:quilboar}свинобраз{/link}ам, отнявшим у него жену.
• Он просит принести клыки Дыб{link:ogres}огр{/link}ивов, чтобы отпраздновать их смерть.
• Он строит памятник в ее честь.]=],
		},
	},
	chapters = {
		{
			title = "Потерянная в бою",
			hint = "Отыщите жену воина Манкрика.",
			text = [=[Манкрик просил лишь о какой-нибудь вести о ней. Ее нашли там, где шел бой, и она была мертва. Он принял весть молча. Потом вернулся к своему дозору.]=],
		},
		{
			title = "Ее зовут Ольгра",
			hint = "Верните украшения жены воина Манкрика.",
			text = [=[Целитель, спасший {link:orcs}орк{/link}а, не смог спасти ее. Ее звали {link:olgra}Ольгра{/link}. Она носила много украшений из полированной кости — собственные произведения искусства, — и они исчезли с ее тела. Манкрик попросил отобрать их у Игл{link:ogres}огр{/link}ивых, которые их унесли, чтобы он мог положить их на ее памятник и никогда ее не забыть.]=],
		},
	},
	mentions = {
		{ text = "Поглощенный ненавистью" },
	},
	bonds = {
		{ id = "olgra", name = "Ольгра", note = "его жена" },
	},
})

