			title = "Значение",
			text = [=[Через него {link:horde}Орда{/link} узнала, кто на самом деле вел набеги Игл{link:ogres}огр{/link}ивых на {link:corin-s-crossing}Перекресток{/link}: трое {link:quilboar}свинобраз{/link}ов, вышедших из {link:razorfen-kraul}Лабиринтов Иглошкурых{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он призывает наносить удары по духовным вождям Дыб{link:ogres}огр{/link}ивов.
• Он назвал предводителей набегов: {link:nak}Нак{/link}, Куз и {link:lok-orcbane}Лок Гроза Орков{/link}.
• Тех, кто приносит ему кровавые осколки, он благословляет силой, которую дарует Агамагган.]=],
		},
	},
	chapters = {
		{
			title = "Измена изнутри",
			hint = [=[Убейте троих свинобразов, которые ведут набеги, как просит Дробозуб.]=],
			text = [=[Лучше, что все кончилось так, сказал Дробозуб, когда трое были мертвы. Им следовало убедиться, что он мертв, прежде чем отворачиваться от него. Голову их предводителя он послал хранителю Перекрестка, зная, что {link:orcs}орк{/link} {link:thork}Торк{/link} никогда не поверит, будто ему помог {link:quilboar}свинобраз{/link}.]=],
		},
	},
	mentions = {
