		{ text = "Кровавые осколки Агамаггана" },
		{ text = "Дух Ветра" },
		{ text = "Сила Агамаггана" },
	},
	bonds = {
		{ id = "lok-orcbane", name = "Лок Гроза Орков", note = "предал его" },
		{ id = "nak", name = "Нак", note = "предал его" },
		{ id = "thork", name = "Торк", note = "получает его дар" },
	},
})

Translate("ruRU", "tonga-runetotem", {
