		{ text = "{link:the-forgotten-pools}Забытые пруды{/link}" },
		{ text = "{link:the-stagnant-oasis}Застывший оазис{/link}" },
		{ text = "Измененные существа" },
		{ text = "Мура Рунический Тотем" },
		{ text = "Исцеление больных" },
		{ text = "Главный источник" },
	},
	bonds = {
		{ id = "hamuul-runetotem", name = "Хамуул Рунический Тотем", note = "послал его в Степи" },
	},
})

Translate("ruRU", "regthar-deathgate", {
	title = "Регтар Врата Смерти",
	subtitle = "Охотник на племя Колкар",
