	subtitle = "Капитан корабля «Беспечный»",
	found = "Пиратские лагеря к югу от Кабестана",
	hint = [=[Сразитесь с капитаном пиратов, который ведет Флибустьеров к югу от Кабестана.]=],
	allegiance = "Флибустьеры Южных морей",
	sections = {
		{
			title = "Обзор",
			text = [=[Барон Лонгшор — капитан корабля «Беспечный», грозного судна Флибустьеров Южных морей. Он уроженец королевства {link:gilneas}Гилнеас{/link}, подавшийся в пираты, и он водит суда Флибустьеров вдоль побережья Степей. {link:gazlowe}Газлоу{/link} назначил цену за его голову и просил доставить его останки в таком виде, чтобы их можно было узнать.]=],
		},
		{
			title = "Значение",
			text = [=[Лонгшор — лицо пиратской угрозы торговле {link:ratchet}Кабестан{/link}а.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он ведет Флибустьеров Южных морей на Торговом побережье.
• Он командует кораблем «Беспечный», чьи паруса знают в открытом море.]=],
		},
	},
	mentions = {
		{ text = "РАЗЫСКИВАЕТСЯ: барон Лонгшор" },
	},
	bonds = {
		{ id = "gazlowe", name = "Газлоу", note = "назначил награду" },
	},
})

Translate("ruRU", "brewmaster-drohn", {
	title = "Хмелевар Дрон",
	subtitle = "Пивовар Кабестана",
	found = "Кабестан",
	hint = [=[Найдите орка-пивовара, который хранит старый пандаренский рецепт.]=],
	allegiance = "Орда",
	aliases = { "Дрон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Хмелевар Дрон — пивовар, хранящий старые рецепты. Его наставник узнал их от странствующего хмелевара Чэня Буйного Портера, который когда-то путешествовал вместе с воином {link:rexxar}Рексар{/link}ом, и передал их ему. Когда в Степях нашелся один из пустых бочонков, которые оставил Чэнь, Дрон не слышал о нем уже целую вечность. Это пробудило в нем воспоминания, и он вновь сварил крепкий грозовой стаут.]=],
		},
		{
			title = "Значение",
			text = [=[Дрон хранит в {link:kalimdor}Калимдор{/link}е нить ремесла, которым владел Чэнь Буйный Портер.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он варит грозовой стаут и {link:troggs}трогг{/link}овый эль по рецептам, которые оставил Чэнь.]=],
		},
	},
	mentions = {
		{ text = "Пустой бочонок хмелевара Чэня" },
		{ text = "Пустой бочонок: грозовой стаут" },
		{ text = "Пустой бочонок: {link:troggs}трогг{/link}овый эль" },
	},
})

Translate("ruRU", "gann-stonespire", {
	title = "Ганн Каменный Шпиль",
	subtitle = "Последний из племени Каменного Шпиля",
	found = "Дорога к северу от Бейл Модана",
	hint = [=[Найдите таурена, который в одиночку бродит по дорогам близ Бейл Модана.]=],
	allegiance = "Племя Каменного Шпиля · Таурены",
	aliases = { "Ганн" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ганн Каменный Шпиль в одиночку бродит по дорогам юга Степей. Земля, где {link:dwarves}дворф{/link}ы теперь ведут раскопки в {link:bael-modan}Бейл Модан{/link}е, была домом и кормилицей его племени. Их взрывы пробивают в ней ямы, а их машины рвут ее на части. Ганн пытался договориться с ними миром и не сумел. Теперь он ищет их дневники, их взрывчатку и гибели их летающей машины.]=],
		},
		{
			title = "Значение",
			text = [=[Ганн — голос племени, потерявшего свою землю. Он просит, чтобы тех, кто сражается за него, помнили в Громовом Утесе как защитников священной земли {link:tauren}таурен{/link}ов.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он пытался заключить мир с {link:dwarves}дворф{/link}ами {link:bael-modan}Бейл Модан{/link}а и потерпел неудачу.
• Он сделал взрывной заряд по чертежам самих дворфов.]=],
		},
	},
	chapters = {
		{
			title = "Месть таурена",
			hint = "Уничтожьте летающую машину Бейл Модана, как просит Ганн.",
			text = [=[Для него летающая машина {link:dwarves}дворф{/link}ов была больше, чем орудие войны. Она была оскорблением памяти его племени. Он собрал заряд по дневнику дворфа-геолога и доверил его тому, кто донесет заряд до машины.]=],
		},
	},
	mentions = {
		{ text = "Возвращение отнятого" },
		{ text = "Месть {link:tauren}таурен{/link}а Ганна" },
	},
})

Translate("ruRU", "walton", {
	title = "Уолтон",
	subtitle = "Кожевник-отшельник",
	found = "Гребень над Сухими холмами",
	hint = [=[Поднимитесь к отшельнику, который живет на гребне над Сухими холмами.]=],
	allegiance = "Нет",
	sections = {
		{
			title = "Обзор",
			text = [=[Уолтон — кожевник, живущий в одиночестве на гребне над Сухими холмами. Он обменивается шкурами с охотником {link:vrang-wildgore}Вранг{/link}ом Диким Рогом, который предупреждает гостей, чтобы те не пугались его вида. Когда-то Уолтон был моряком флота {link:kul-tiras}Кул Тираса{/link}. Когда {link:daelin-proudmoore}Делин Праудмур{/link} пошел войной на Орду, Уолтон воспротивился методам адмирала, и прежде всего убийству мирных жителей. В его истории есть и другое, говорит он, и рассказывает не все.]=],
		},
		{
			title = "Значение",
			text = [=[Уолтон — свидетельство того, что не каждый уроженец {link:kul-tiras}Кул Тирас{/link}а шел за адмиралом по доброй воле. {link:humans}Люди{/link}, которые все еще поднимают знамя адмирала, его не забыли.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он оставил службу у адмирала из-за убийства мирных жителей.
• Он выделывает шкуры, которые приносит ему {link:vrang-wildgore}Вранг Дикий Рог{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Незваные гости",
			hint = [=[Встаньте рядом с отшельником, когда на гребень поднимутся чужаки.]=],
			text = [=[На гребень поднялся отряд: охотник за головами Терри Долгий Глоток и морские пехотинцы {link:kul-tiras}Кул Тирас{/link}а. Они пришли за отшельником. Когда бой кончился, а он остался жив, Уолтон сказал, что всегда знал: когда-нибудь это его настигнет.]=],
		},
		{
			title = "Беда в долине",
			hint = [=[Узнайте, почему солдаты Кул Тираса стоят лагерем у разбитого каравана.]=],
			text = [=[Уолтон видел, как люди в цветах {link:kul-tiras}Кул Тирас{/link}а обыскивают долину внизу. Приказы, найденные в их лагере, исходили из Крепости Тирагард, от лейтенанта {link:archbishop-benedictus}Бенедикт{/link}а. Они охотились на дезертира. Прошлое, сказал Уолтон, наконец его настигло.]=],
		},
	},
	mentions = {
		{ text = "Кожевник-отшельник" },
	},
	bonds = {
		{ id = "vrang-wildgore", name = "Вранг Дикий Рог", note = "обменивается с ним шкурами" },
		{ id = "daelin-proudmoore", name = "Делин Праудмур", note = "адмирал, которому он воспротивился" },
		{ id = "lieutenant-benedict", name = "Лейтенант Бенедикт", note = "послал людей найти его" },
	},
})

Translate("ruRU", "vrang-wildgore", {
	title = "Вранг Дикий Рог",
	subtitle = "Зверолов Сухих холмов",
	found = "Долина под Сухими холмами",
	hint = [=[Поговорите с раненым охотником, который держит ловушки в долине под Сухими холмами.]=],
	allegiance = "Орда",
	aliases = { "Вранг" },
	sections = {
		{
			title = "Обзор",
			text = [=[Вранг Дикий Рог — охотник и зверолов севера Степей. Недавняя рана в ногу не дает ему ни охотиться, ни взбираться на кручи, и его гордость уязвлена тем, что приходится просить помощи у чужаков. Но у него есть обязательства, которые надо держать. Он отдает сырые львиные шкуры кожевнику, живущему на гребне над ним, а взамен получает выделанную кожу для своего ремесла.]=],
		},
		{
			title = "Значение",
			text = [=[Вранг — единственный друг отшельника {link:walton}Уолтон{/link}а, и он ручается за него перед всяким, кто спросит.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он собирает шкуры больших саванных львов.
• Он держит ловушки по всей долине под Сухими холмами.]=],
		},
	},
	mentions = {
		{ text = "Уязвленная гордость и львиные шкуры" },
		{ text = "Кожевник-отшельник" },
		{ text = "Дичь зверолова" },
	},
	bonds = {
		{ id = "walton", name = "Уолтон", note = "его товарищ по обмену" },
	},
})

Translate("ruRU", "chol-aruk", {
	title = "Чол'арук",
	subtitle = "Пожиратель",
	found = "Пещера на плато Тернистого холма",
	hint = "Найдите логово зверя, которого Иглогривые зовут Пожирателем.",
	allegiance = "Свинобразы племени Иглогривых",
	aliases = { "Пожиратель" },
	sections = {
		{
			title = "Обзор",
			text = [=[Чол'арук — чудовищный {link:quilboar}свинобраз{/link}, устроивший логово в пещере на Тернистом холме. {link:razormane-quilboar}Иглогривые{/link} зовут его Пожирателем. Те, кто его видел, говорят, что он впятеро больше обычного свинобраза, что его жажда крови неутолима и что он мог бы проглотить {link:orcs}орк{/link}а целиком. Большинство не верит таким рассказам. Им верит Гур'ак с Перекрестка, и верит {link:baine-bloodhoof}Бейн{/link}хем, солдат {link:alliance}Альянс{/link}а в {link:ratchet}Кабестан{/link}е. Каждый из них прежде бился с подобным зверем, и каждый потерял в том бою товарищей.]=],
		},
		{
			title = "Значение",
			text = [=[Чол'арук — недобрый знак. Если бы таких чудовищ среди {link:quilboar}свинобраз{/link}ов стало больше, вред, который они могли бы причинить этой земле, был бы ужасен.]=],
		},
		{ title = "Деяния", text = "• Его логово лежит в глубинах Тернистого холма." },
	},
	mentions = {
		{ text = "Чол'арук, Пожиратель: поручение, которое дает Гур'ак" },
		{
			text = [=[Чол'арук, Пожиратель: поручение, которое дает {link:baine-bloodhoof}Бейн{/link}хем]=],
		},
	},
})

Translate("ruRU", "kolkar-centaurs", {
	title = "Кентавры племени Колкар",
	aliases = { "Колкар", "племя Колкар" },
	sections = {
		{
			title = "Обзор",
			text = [=[Колкар — племя {link:centaurs}кентавров{/link}, кочующее по Степям и окрестным землям. Его всадники стоят лагерем у оазисов, охотятся на зверей, приходящих на водопой, и нападают на путников на дорогах. Они годами совершали набеги на {link:tauren}таурен{/link}ов до прихода {link:orcs}орк{/link}ов и с тех пор не перестают совершать их на Орду.]=],
		},
		{
			title = "В наши дни",
			text = [=[Долгое время {link:centaurs}кентавр{/link}ы племени Колкар в Степях были рассеяны и не знали порядка. Теперь среди них поднялись новые предводители: {link:barak-kodobane}Барак Гроза Кодо{/link} близ Забытых прудов, {link:verog-the-dervish}Верог Дервиш{/link} у Застывшего оазиса и величайший из них, {link:hezrul-bloodmark}Хезрул Кровавая Метка{/link}, у Цветущего оазиса. При этих вождях племя стало настоящей угрозой. {link:regthar-deathgate}Регтар Врата Смерти{/link} охотится на них из своих бункеров к западу от Перекрестка, а когда их предводители пали, из родных земель племени в {link:desolace}Пустошах{/link} пришел боевой отряд, чтобы отомстить. В {link:durotar}Дуротаре{/link} другой отряд держит скалистое ущелье — {link:kolkar-crag}Утес Колкара{/link}.]=],
		},
	},
})

Translate("ruRU", "razormane-quilboar", {
	title = "Свинобразы племени Иглогривых",
	aliases = { "Иглогривые", "племя Иглогривых" },
	sections = {
		{
			title = "Обзор",
			text = [=[Иглогривые — племя {link:quilboar}свинобразов{/link} севера и юга Степей. Они ставят свои станы среди {link:ogres}огр{/link}омных колючих лоз, растущих из земли, и чтят вепря-духа Агамаггана, чья кровь, как говорят, породила эти шипы. До прихода {link:orcs}орк{/link}ов они кочевали по земле, которая теперь зовется {link:durotar}Дуротаром{/link}, и так и не смирились с ее потерей.]=],
		},
		{
			title = "В наши дни",
			text = [=[Иглогривые воюют с Ордой и со своими родичами из племени Дыб{link:ogres}огр{/link}ивов. Они держат {link:thorn-hill}Тернистый холм{/link} к востоку от Перекрестка, {link:bramblescar}Ежевичный овраг{/link} на срединных равнинах и {link:blackthorn-ridge}Хребет Черных Шипов{/link} на юге. Их набеги на караваны из {link:durotar}Дуротар{/link}а вели трое из их племени, вышедшие из {link:razorfen-kraul}Лабиринтов Иглошкурых{/link}: {link:nak}Нак{/link}, Куз и {link:lok-orcbane}Лок Гроза Орков{/link}. Кузнец Лагеря {link:camp-taurajo}Таурахо{/link} обнаружил, что их оружие становится прочнее. В пещере на Тернистом холме, как говорят Иглогривые, живет чудовищный зверь их собственной крови — {link:chol-aruk}Пожиратель{/link}.]=],
		},
	},
})
